[CmdletBinding()]
param(
    [string]$DsweepPath,
    [string]$OutputDirectory = (Join-Path (Split-Path -Parent $PSScriptRoot) 'dist/demo')
)

$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path -Parent $PSScriptRoot
$outputParent = [IO.Path]::GetFullPath($OutputDirectory)
$runRoot = Join-Path $outputParent ('run-' + [Guid]::NewGuid().ToString('N'))
$fixtureRoot = Join-Path $runRoot 'fixture'
$fixtureCreated = $false

if ($DsweepPath) {
    $script:DsweepPath = (Resolve-Path -LiteralPath $DsweepPath).Path
}
$script:repoRoot = $repoRoot

function Invoke-DupeSweep {
    param(
        [string[]]$Arguments,
        [string]$StdoutPath,
        [string]$StderrPath
    )

    $previousErrorAction = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        if ($script:DsweepPath) {
            & $script:DsweepPath @Arguments 1> $StdoutPath 2> $StderrPath
        }
        else {
            & dotnet run --project (Join-Path $script:repoRoot 'src/DupeSweep') --configuration Release --no-build -- @Arguments 1> $StdoutPath 2> $StderrPath
        }
        $exitCode = $LASTEXITCODE
    }
    finally {
        $ErrorActionPreference = $previousErrorAction
    }

    if ($exitCode -ne 0) {
        throw "dsweep failed with exit code $exitCode. See $StderrPath"
    }
}

function Get-FileEvidence {
    param([string]$Path)

    $hash = (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
    [ordered]@{ path = $Path; length = (Get-Item -LiteralPath $Path).Length; sha256 = $hash }
}

try {
    New-Item -ItemType Directory -Path $runRoot -Force | Out-Null
    New-Item -ItemType Directory -Path $fixtureRoot -Force | Out-Null
    $fixtureCreated = $true

    if (-not $script:DsweepPath) {
        $buildLog = Join-Path $runRoot 'build.log'
        & dotnet build (Join-Path $script:repoRoot 'DupeSweep.slnx') --configuration Release 1> $buildLog 2>&1
        if ($LASTEXITCODE -ne 0) {
            throw "dotnet build failed with exit code $LASTEXITCODE. See $buildLog"
        }
    }

    # Exact byte arrays make equal lengths and different content independent of text encoding.
    $duplicateBytes = [byte[]](0..255 | ForEach-Object { $_ })
    $differentBytes = [byte[]](255..0 | ForEach-Object { $_ })
    $duplicateA = Join-Path $fixtureRoot 'duplicate-a.bin'
    $duplicateB = Join-Path $fixtureRoot 'duplicate-b.bin'
    $differentA = Join-Path $fixtureRoot 'same-size-a.bin'
    $differentB = Join-Path $fixtureRoot 'same-size-b.bin'
    [IO.File]::WriteAllBytes($duplicateA, $duplicateBytes)
    [IO.File]::WriteAllBytes($duplicateB, $duplicateBytes)
    [IO.File]::WriteAllBytes($differentA, $differentBytes)
    # Keep the same length while making the second file's bytes different.
    $differentBytes[0] = 254
    [IO.File]::WriteAllBytes($differentB, $differentBytes)

    $fixtureFiles = @($duplicateA, $duplicateB, $differentA, $differentB)
    $before = @($fixtureFiles | ForEach-Object { Get-FileEvidence $_ })
    $before | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $runRoot 'hashes-before.json')

    $reportPath = Join-Path $runRoot 'report.json'
    $scanStderr = Join-Path $runRoot 'scan.stderr.txt'
    Invoke-DupeSweep @($fixtureRoot, '--json') $reportPath $scanStderr
    $report = Get-Content -Raw -LiteralPath $reportPath | ConvertFrom-Json
    if ($report.summary.groupCount -ne 1 -or $report.summary.duplicateFileCount -ne 1) {
        throw "expected one duplicate group and one duplicate file; got $($report.summary.groupCount) groups and $($report.summary.duplicateFileCount) duplicates"
    }
    $reportedDuplicate = @($report.groups[0].duplicates | Where-Object { $_ -match 'duplicate-[ab]\.bin' })
    if ($reportedDuplicate.Count -ne 1) {
        throw 'the report did not identify exactly one generated duplicate file'
    }
    if (($report.groups | ConvertTo-Json -Depth 5) -match 'same-size-[ab]\.bin') {
        throw 'same-size files with different bytes were incorrectly reported as duplicates'
    }
    foreach ($entry in $before) {
        if (-not (Test-Path -LiteralPath $entry.path)) { throw "report-only scan moved or deleted $($entry.path)" }
        if ((Get-FileEvidence $entry.path).sha256 -ne $entry.sha256) { throw "report-only scan changed $($entry.path)" }
    }

    $quarantineRoot = Join-Path $fixtureRoot '.dupesweep-quarantine'
    $applyStdout = Join-Path $runRoot 'apply.stdout.txt'
    $applyStderr = Join-Path $runRoot 'apply.stderr.txt'
    Invoke-DupeSweep @($fixtureRoot, '--apply', 'quarantine', '--quarantine-dir', $quarantineRoot) $applyStdout $applyStderr
    $manifestPath = Join-Path $quarantineRoot 'manifest.json'
    if (-not (Test-Path -LiteralPath $manifestPath)) { throw 'quarantine did not produce manifest.json' }
    $manifest = @(Get-Content -Raw -LiteralPath $manifestPath | ConvertFrom-Json)
    if ($manifest.Count -ne 1 -or -not (Test-Path -LiteralPath $manifest[0].quarantinePath)) {
        throw 'quarantine manifest does not describe the moved duplicate'
    }
    $manifestEvidencePath = Join-Path $runRoot 'manifest.json'
    Copy-Item -LiteralPath $manifestPath -Destination $manifestEvidencePath
    $quarantineBeforeDryRun = Get-FileEvidence $manifest[0].quarantinePath
    if (Test-Path -LiteralPath $manifest[0].originalPath) {
        throw 'quarantine did not move the duplicate away from its original path'
    }
    foreach ($entry in $before) {
        if ($entry.path -eq $manifest[0].originalPath) { continue }
        if (-not (Test-Path -LiteralPath $entry.path)) { throw "quarantine changed nonduplicate file $($entry.path)" }
        if ((Get-FileEvidence $entry.path).sha256 -ne $entry.sha256) { throw "quarantine changed $($entry.path)" }
    }

    $dryRunPath = Join-Path $runRoot 'restore-dry-run.txt'
    $dryRunErr = Join-Path $runRoot 'restore-dry-run.stderr.txt'
    Invoke-DupeSweep @('restore', $manifestPath, '--dry-run') $dryRunPath $dryRunErr
    if (Test-Path -LiteralPath $manifest[0].originalPath) { throw 'restore dry-run recreated the original file' }
    if (-not (Test-Path -LiteralPath $manifest[0].quarantinePath)) { throw 'restore dry-run moved the quarantined file' }
    if ((Get-FileEvidence $manifest[0].quarantinePath).sha256 -ne $quarantineBeforeDryRun.sha256) {
        throw 'restore dry-run changed the quarantined file'
    }

    $restorePath = Join-Path $runRoot 'restore.txt'
    $restoreErr = Join-Path $runRoot 'restore.stderr.txt'
    Invoke-DupeSweep @('restore', $manifestPath) $restorePath $restoreErr
    if (-not (Test-Path -LiteralPath $manifest[0].originalPath)) { throw 'restore did not recreate the original duplicate path' }
    $after = @($fixtureFiles | ForEach-Object { Get-FileEvidence $_ })
    $after | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $runRoot 'hashes-after.json')
    foreach ($entry in $before) {
        $restored = $after | Where-Object { $_.path -eq $entry.path }
        if (-not $restored -or $restored.sha256 -ne $entry.sha256 -or $restored.length -ne $entry.length) {
            throw "roundtrip changed $($entry.path)"
        }
    }

    [ordered]@{
        status = 'passed'
        fixture = $fixtureRoot
        report = $reportPath
        manifest = $manifestEvidencePath
        duplicateGroups = $report.summary.groupCount
        duplicateFiles = $report.summary.duplicateFileCount
        sameSizeNonduplicatesExcluded = $true
        roundtripHashesMatch = $true
    } | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $runRoot 'demo-summary.json')
    Write-Output "DupeSweep safe demo passed. Evidence: $runRoot"
}
finally {
    if ($fixtureCreated -and (Test-Path -LiteralPath $fixtureRoot)) {
        # This path was generated above; never remove a caller-supplied input path.
        Remove-Item -LiteralPath $fixtureRoot -Recurse -Force
    }
}

[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [string] $BinaryPath,

    [string] $EvidenceDirectory,

    [switch] $KeepFixture
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Get-TreeSnapshot {
    param([Parameter(Mandatory = $true)][string] $Directory)

    if (-not (Test-Path -LiteralPath $Directory -PathType Container)) {
        return ''
    }

    $rootPath = (Resolve-Path -LiteralPath $Directory).Path
    $rootPath = $rootPath.TrimEnd([char[]]@('\', '/')) + [IO.Path]::DirectorySeparatorChar
    $items = Get-ChildItem -LiteralPath $Directory -File -Recurse | Sort-Object FullName
    $snapshot = foreach ($item in $items) {
        [pscustomobject]@{
            Path = $item.FullName.Substring($rootPath.Length)
            Length = $item.Length
            SHA256 = (Get-FileHash -LiteralPath $item.FullName -Algorithm SHA256).Hash
        }
    }
    if ($null -eq $snapshot) {
        return ''
    }
    return ($snapshot | ConvertTo-Json -Compress)
}

function Assert-SameSnapshot {
    param(
        [Parameter(Mandatory = $true)][string] $Before,
        [Parameter(Mandatory = $true)][string] $After,
        [Parameter(Mandatory = $true)][string] $Description
    )

    if ($Before -cne $After) {
        throw "Fixture changed during $Description."
    }
}

function Write-FixtureBytes {
    param([Parameter(Mandatory = $true)][string] $Path, [Parameter(Mandatory = $true)][byte[]] $Bytes)

    $parent = Split-Path -Parent $Path
    New-Item -ItemType Directory -Path $parent -Force | Out-Null
    [IO.File]::WriteAllBytes($Path, $Bytes)
}

function Invoke-Dsweep {
    param(
        [Parameter(Mandatory = $true)][string[]] $Arguments,
        [Parameter(Mandatory = $true)][string] $StdoutPath,
        [Parameter(Mandatory = $true)][string] $StderrPath
    )

    $previousErrorAction = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        & $script:resolvedBinary @Arguments 1> $StdoutPath 2> $StderrPath
        return $LASTEXITCODE
    }
    finally {
        $ErrorActionPreference = $previousErrorAction
    }
}

$resolvedBinary = (Resolve-Path -LiteralPath $BinaryPath -ErrorAction Stop).Path
$binaryDirectory = Split-Path -Parent $resolvedBinary
if (-not (Test-Path -LiteralPath (Join-Path $binaryDirectory 'LICENSE') -PathType Leaf)) {
    throw "Package is missing LICENSE beside the binary."
}
if (-not (Test-Path -LiteralPath (Join-Path $binaryDirectory 'USAGE.md') -PathType Leaf)) {
    throw "Package is missing USAGE.md beside the binary."
}

$fixtureRoot = Join-Path ([IO.Path]::GetTempPath()) "dupesweep-smoke-$([guid]::NewGuid().ToString('N'))"
$fixture = Join-Path $fixtureRoot 'fixture'
$quarantine = Join-Path $fixtureRoot 'quarantine'
$logs = if ([string]::IsNullOrWhiteSpace($EvidenceDirectory)) {
    Join-Path $fixtureRoot 'logs'
}
else {
    [IO.Path]::GetFullPath($EvidenceDirectory)
}
$created = $false

try {
    New-Item -ItemType Directory -Path $fixture, $quarantine, $logs -Force | Out-Null
    $created = $true

    $duplicateBytes = [byte[]](0..127)
    $otherBytes = [byte[]](128..255)
    Write-FixtureBytes (Join-Path $fixture 'keep.bin') $duplicateBytes
    Write-FixtureBytes (Join-Path $fixture 'nested\copy.bin') $duplicateBytes
    Write-FixtureBytes (Join-Path $fixture 'same-size-but-unique.bin') $otherBytes

    $initialSnapshot = Get-TreeSnapshot $fixture
    $reportPath = Join-Path $logs 'report.json'
    $reportErrorPath = Join-Path $logs 'report.stderr'
    $exitCode = Invoke-Dsweep @($fixture, '--json', '--quiet') $reportPath $reportErrorPath
    if ($exitCode -ne 0) { throw "JSON report failed with exit code $exitCode." }

    $report = Get-Content -LiteralPath $reportPath -Raw | ConvertFrom-Json
    if ($report.summary.groupCount -ne 1 -or $report.summary.duplicateFileCount -ne 1) {
        throw "Expected one duplicate group with one duplicate file in the report."
    }
    if (-not (Test-Path -LiteralPath (Join-Path $fixture 'same-size-but-unique.bin') -PathType Leaf)) {
        throw 'Same-size nonduplicate fixture is missing before apply.'
    }
    Assert-SameSnapshot $initialSnapshot (Get-TreeSnapshot $fixture) 'report generation'

    $applyOutput = Join-Path $logs 'apply.stdout'
    $applyError = Join-Path $logs 'apply.stderr'
    $exitCode = Invoke-Dsweep @($fixture, '--apply', 'quarantine', '--quarantine-dir', $quarantine, '--quiet') $applyOutput $applyError
    if ($exitCode -ne 0) { throw "Quarantine apply failed with exit code $exitCode." }

    $manifestPath = Join-Path $quarantine 'manifest.json'
    if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) {
        throw 'Quarantine apply did not create a manifest.'
    }
    $manifest = @(Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json)
    if ($manifest.Count -ne 1) { throw "Expected one manifest entry, found $($manifest.Count)." }
    $entry = $manifest[0]
    if (Test-Path -LiteralPath $entry.originalPath -PathType Leaf) {
        throw 'Quarantined duplicate still exists at its original path.'
    }
    if (-not (Test-Path -LiteralPath $entry.quarantinePath -PathType Leaf)) {
        throw 'Manifest quarantine path does not exist.'
    }
    $originalHash = (Get-FileHash -LiteralPath (Join-Path $fixture 'keep.bin') -Algorithm SHA256).Hash
    $quarantineHash = (Get-FileHash -LiteralPath $entry.quarantinePath -Algorithm SHA256).Hash
    if ($originalHash -cne $quarantineHash) { throw 'Quarantine changed duplicate bytes.' }
    if (-not (Test-Path -LiteralPath (Join-Path $fixture 'same-size-but-unique.bin') -PathType Leaf)) {
        throw 'Same-size nonduplicate was moved by quarantine.'
    }

    $beforeDryRun = "$(Get-TreeSnapshot $fixture)`n$(Get-TreeSnapshot $quarantine)"
    $dryOutput = Join-Path $logs 'restore-dry-run.stdout'
    $dryError = Join-Path $logs 'restore-dry-run.stderr'
    $exitCode = Invoke-Dsweep @('restore', $manifestPath, '--dry-run') $dryOutput $dryError
    if ($exitCode -ne 0) { throw "Restore dry-run failed with exit code $exitCode." }
    if (-not ((Get-Content -LiteralPath $dryOutput -Raw) -match 'restore preview')) {
        throw 'Restore dry-run did not report preview mode.'
    }
    $afterDryRun = "$(Get-TreeSnapshot $fixture)`n$(Get-TreeSnapshot $quarantine)"
    Assert-SameSnapshot $beforeDryRun $afterDryRun 'restore dry-run'

    $restoreOutput = Join-Path $logs 'restore.stdout'
    $restoreError = Join-Path $logs 'restore.stderr'
    $exitCode = Invoke-Dsweep @('restore', $manifestPath) $restoreOutput $restoreError
    if ($exitCode -ne 0) { throw "Restore failed with exit code $exitCode." }
    Assert-SameSnapshot $initialSnapshot (Get-TreeSnapshot $fixture) 'restore'
    if (Test-Path -LiteralPath $entry.quarantinePath) { throw 'Restore left a quarantined file behind.' }

    $beforeRefusal = Get-TreeSnapshot $fixture
    Write-FixtureBytes (Join-Path $fixture 'second-copy.bin') $duplicateBytes
    $beforeRefusal = Get-TreeSnapshot $fixture
    $refusalOutput = Join-Path $logs 'overwrite-refusal.stdout'
    $refusalError = Join-Path $logs 'overwrite-refusal.stderr'
    $exitCode = Invoke-Dsweep @($fixture, '--apply', 'quarantine', '--quarantine-dir', $quarantine, '--quiet') $refusalOutput $refusalError
    if ($exitCode -eq 0) { throw 'Quarantine unexpectedly reused an existing manifest.' }
    Assert-SameSnapshot $beforeRefusal (Get-TreeSnapshot $fixture) 'existing-manifest refusal'

    $invalidOutput = Join-Path $logs 'invalid-option.stdout'
    $invalidError = Join-Path $logs 'invalid-option.stderr'
    $exitCode = Invoke-Dsweep @('--definitely-invalid') $invalidOutput $invalidError
    if ($exitCode -ne 2) { throw "Invalid CLI option returned $exitCode instead of 2." }

    $overwriteQuarantine = Join-Path $fixtureRoot 'overwrite-quarantine'
    $overwriteOriginal = Join-Path $fixture 'restore-sentinel.bin'
    $overwritePayload = Join-Path $overwriteQuarantine 'payload.bin'
    $overwriteManifest = Join-Path $overwriteQuarantine 'manifest.json'
    $sentinelBytes = [byte[]](7..18)
    $payloadBytes = [byte[]](19..30)
    Write-FixtureBytes $overwriteOriginal $sentinelBytes
    Write-FixtureBytes $overwritePayload $payloadBytes
    $payloadHash = (Get-FileHash -LiteralPath $overwritePayload -Algorithm SHA256).Hash
    $overwriteManifestJson = ConvertTo-Json -InputObject @([ordered]@{
        originalPath = $overwriteOriginal
        quarantinePath = $overwritePayload
        length = $payloadBytes.Length
        hash = (Get-FileHash -LiteralPath $overwritePayload -Algorithm SHA256).Hash
    })
    $overwriteManifestJson | Set-Content -LiteralPath $overwriteManifest -Encoding utf8
    $sentinelBefore = Get-TreeSnapshot $fixture
    $payloadBefore = Get-TreeSnapshot $overwriteQuarantine
    $overwriteOutput = Join-Path $logs 'restore-overwrite.stdout'
    $overwriteError = Join-Path $logs 'restore-overwrite.stderr'
    $exitCode = Invoke-Dsweep @('restore', $overwriteManifest) $overwriteOutput $overwriteError
    if ($exitCode -eq 0) { throw 'Restore unexpectedly overwrote an existing destination.' }
    Assert-SameSnapshot $sentinelBefore (Get-TreeSnapshot $fixture) 'restore destination refusal'
    Assert-SameSnapshot $payloadBefore (Get-TreeSnapshot $overwriteQuarantine) 'restore destination refusal'

    Remove-Item -LiteralPath $overwriteOriginal -Force
    $overwriteRestoreOutput = Join-Path $logs 'restore-overwrite-retry.stdout'
    $overwriteRestoreError = Join-Path $logs 'restore-overwrite-retry.stderr'
    $exitCode = Invoke-Dsweep @('restore', $overwriteManifest) $overwriteRestoreOutput $overwriteRestoreError
    if ($exitCode -ne 0) { throw "Restore after clearing owned sentinel failed with exit code $exitCode." }
    $restoredHash = (Get-FileHash -LiteralPath $overwriteOriginal -Algorithm SHA256).Hash
    if ($restoredHash -cne $payloadHash) { throw 'Restore destination test changed payload bytes.' }

    Write-Output "Smoke passed: report, same-size exclusion, quarantine, SHA256 preservation, dry-run, restore, manifest refusal, destination refusal, and CLI error exit."
}
catch {
    $failurePath = Join-Path $logs 'smoke-failure.txt'
    $_ | Out-String | Set-Content -LiteralPath $failurePath -Encoding utf8
    Write-Error $_
    exit 1
}
finally {
    if ($created -and -not $KeepFixture -and (Test-Path -LiteralPath $fixtureRoot)) {
        Remove-Item -LiteralPath $fixtureRoot -Recurse -Force
    }
    elseif ($created -and $KeepFixture) {
        Write-Output "Smoke fixture retained at: $fixtureRoot"
    }
}

using System.Reflection;

namespace DupeSweep;

/// <summary>
/// Exposes the release version compiled into this assembly so a bug report can name the exact build.
/// </summary>
/// <remarks>
/// The value is read from the assembly's informational version, which the .NET SDK derives from the
/// MSBuild <c>Version</c> property declared once in <c>DupeSweep.csproj</c>. Nothing here hardcodes a
/// version string, so a release that builds with a different <c>Version</c> reports that value too.
/// </remarks>
public static class BuildInfo
{
    /// <summary>Product name used in user-facing version output.</summary>
    public const string ProductName = "DupeSweep";

    /// <summary>
    /// The release version, for example <c>1.0.1</c>. Build metadata (the part after <c>+</c> that the
    /// SDK may append from source-control revision) is dropped so the reported value matches the
    /// published release label.
    /// </summary>
    public static string Version { get; } = ResolveVersion();

    /// <summary>The single line printed by <c>dsweep --version</c>.</summary>
    public static string Describe() => $"{ProductName} {Version}";

    private static string ResolveVersion()
    {
        Assembly assembly = typeof(BuildInfo).Assembly;

        string? informationalVersion = assembly
            .GetCustomAttribute<AssemblyInformationalVersionAttribute>()?
            .InformationalVersion;

        if (!string.IsNullOrWhiteSpace(informationalVersion))
        {
            int metadataSeparator = informationalVersion.IndexOf('+');
            return (metadataSeparator >= 0 ? informationalVersion[..metadataSeparator] : informationalVersion).Trim();
        }

        Version? assemblyVersion = assembly.GetName().Version;
        return assemblyVersion is null ? "unknown" : assemblyVersion.ToString(3);
    }
}

using System.Globalization;

namespace DupeSweep;

/// <summary>Parses argv into <see cref="ScanOptions"/> and renders usage.</summary>
public static class CommandLine
{
    public static ScanOptions Parse(string[] args)
    {
        var options = new ScanOptions();

        if (args.Length > 0 && string.Equals(args[0], "restore", StringComparison.OrdinalIgnoreCase))
        {
            options.RestoreMode = true;
            ParseRestoreArgs(args, options);
            return options;
        }

        for (int i = 0; i < args.Length; i++)
        {
            string arg = args[i];
            switch (arg)
            {
                case "-h":
                case "--help":
                    options.Help = true;
                    break;
                case "--version":
                    options.ShowVersion = true;
                    break;
                case "--no-recursive":
                    options.Recursive = false;
                    break;
                case "--min-size":
                    options.MinSizeBytes = ParseSize(RequireValue(args, ref i, arg));
                    break;
                case "--ext":
                    options.Extensions = NormalizeExtensions(RequireValue(args, ref i, arg));
                    break;
                case "--exclude":
                    options.Excludes.Add(RequireValue(args, ref i, arg));
                    break;
                case "--follow-symlinks":
                    options.FollowSymlinks = true;
                    break;
                case "--json":
                    options.Json = true;
                    break;
                case "--apply":
                    options.Apply = ParseApplyMode(RequireValue(args, ref i, arg));
                    break;
                case "--quarantine-dir":
                    options.QuarantineDir = RequireValue(args, ref i, arg);
                    break;
                case "--keep":
                    options.Keep = ParseKeepStrategy(RequireValue(args, ref i, arg));
                    break;
                case "-j":
                case "--parallel":
                    options.Parallelism = Math.Clamp(int.Parse(RequireValue(args, ref i, arg), CultureInfo.InvariantCulture), 1, 64);
                    break;
                case "-q":
                case "--quiet":
                    options.Quiet = true;
                    break;
                case "-v":
                case "--verbose":
                    options.Verbose = true;
                    break;
                default:
                    if (arg.StartsWith('-'))
                        throw new ArgumentException($"unknown option '{arg}' (try --help)");
                    options.Roots.Add(arg);
                    break;
            }
        }

        return options;
    }

    private static void ParseRestoreArgs(string[] args, ScanOptions options)
    {
        for (int i = 1; i < args.Length; i++)
        {
            string arg = args[i];
            switch (arg)
            {
                case "-h":
                case "--help":
                    options.Help = true;
                    break;
                case "--version":
                    options.ShowVersion = true;
                    break;
                case "--dry-run":
                    options.DryRun = true;
                    break;
                case "-q":
                case "--quiet":
                    options.Quiet = true;
                    break;
                default:
                    if (arg.StartsWith('-'))
                        throw new ArgumentException($"unknown option '{arg}' (try --help)");
                    if (options.ManifestPath is not null)
                        throw new ArgumentException("restore takes exactly one manifest path");
                    options.ManifestPath = arg;
                    break;
            }
        }
    }

    private static string RequireValue(string[] args, ref int i, string flag)
    {
        if (i + 1 >= args.Length)
            throw new ArgumentException($"option '{flag}' requires a value");
        return args[++i];
    }

    private static long ParseSize(string raw)
    {
        raw = raw.Trim();
        if (raw.Length == 0)
            throw new ArgumentException("size value cannot be empty");

        char suffix = char.ToUpperInvariant(raw[^1]);
        long multiplier = suffix switch
        {
            'K' => 1024L,
            'M' => 1024L * 1024,
            'G' => 1024L * 1024 * 1024,
            _ => 1L,
        };
        string numberPart = multiplier == 1 ? raw : raw[..^1];
        if (!double.TryParse(numberPart, NumberStyles.Float, CultureInfo.InvariantCulture, out double value) || value < 0)
            throw new ArgumentException($"invalid size '{raw}'");
        return (long)(value * multiplier);
    }

    private static string[] NormalizeExtensions(string raw) =>
        raw.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
           .Select(e => e.StartsWith('.') ? e.ToLowerInvariant() : "." + e.ToLowerInvariant())
           .ToArray();

    private static ApplyMode ParseApplyMode(string raw) => raw.ToLowerInvariant() switch
    {
        "quarantine" => ApplyMode.Quarantine,
        "delete" => ApplyMode.Delete,
        _ => throw new ArgumentException($"invalid --apply mode '{raw}' (expected 'quarantine' or 'delete')"),
    };

    private static KeepStrategy ParseKeepStrategy(string raw) => raw.ToLowerInvariant() switch
    {
        "first" => KeepStrategy.First,
        "oldest" => KeepStrategy.Oldest,
        "newest" => KeepStrategy.Newest,
        "shortest-path" => KeepStrategy.ShortestPath,
        _ => throw new ArgumentException($"invalid --keep strategy '{raw}' (expected first, oldest, newest or shortest-path)"),
    };

    public static string Usage =>
        """
        dsweep - DupeSweep: a fast duplicate-file finder and reclaimer

        USAGE:
          dsweep <dir> [dir2 ...] [options]
          dsweep restore <manifest.json> [--dry-run]

        OPTIONS:
              --no-recursive       Only scan the given directories, not subdirectories.
              --min-size <size>    Ignore files smaller than this (default 1; 0 includes empty files), e.g. 4K, 10M.
              --ext <list>         Only consider these extensions, e.g. .jpg,.png
              --exclude <glob>     Exclude files/directories matching a glob (repeatable), e.g. node_modules, *.tmp
              --follow-symlinks    Follow symlinked files and directories with cycle detection (off by default).
              --keep <strategy>    Which copy to keep per group: first (default), oldest, newest, shortest-path.
              --apply <mode>       Act on duplicates: 'quarantine' (movable/reversible) or 'delete' (permanent).
              --quarantine-dir <p> Destination for --apply quarantine (default: <first-dir>/.dupesweep-quarantine).
          -j, --parallel <n>       Hashing worker count (default: CPU core count, max 64).
              --json               Emit a machine-readable JSON report instead of text.
          -q, --quiet              Minimal output.
          -v, --verbose            Verbose logging (reports skipped/unreadable files).
              --version            Print the DupeSweep version and exit without scanning file contents.
          -h, --help               Show this help.

        RESTORE:
              --dry-run            Preview what would be restored without moving anything.

        EXAMPLES:
          dsweep ~/Downloads
          dsweep ~/Photos ~/Backups/Photos --ext .jpg,.png --keep oldest
          dsweep . --exclude node_modules --exclude .git --apply quarantine
          dsweep restore ~/Downloads/.dupesweep-quarantine/manifest.json
        """;
}

using System.Collections.Concurrent;

namespace DupeSweep;

/// <summary>
/// Finds true duplicates through a three-stage funnel — cheap checks first, expensive ones last:
/// group by file size, then by a 64 KB quick hash, then confirm with a full SHA-256 hash.
/// </summary>
public sealed class DuplicateFinder(ScanOptions options)
{
    public async Task<DuplicateScanResult> FindGroupsAsync(IReadOnlyList<FileEntry> entries, CancellationToken ct)
    {
        var warnings = new List<string>();

        List<FileEntry> bySize = entries
            .GroupBy(e => e.Length)
            .Where(g => g.Count() > 1)
            .SelectMany(g => g)
            .ToList();

        (Dictionary<string, List<FileEntry>> byQuickHash, List<string> quickWarnings) = await GroupByAsync(
            bySize,
            e => Task.FromResult(Hashing.ComputeQuickHash(e.FullPath, e.Length, ct)),
            ct).ConfigureAwait(false);
        warnings.AddRange(quickWarnings);

        List<FileEntry> candidates = byQuickHash.Values
            .Where(g => g.Count > 1)
            .SelectMany(g => g)
            .ToList();

        (Dictionary<string, List<FileEntry>> byFullHash, List<string> fullWarnings) = await GroupByAsync(
            candidates,
            e => Hashing.ComputeFullHashAsync(e.FullPath, ct),
            ct).ConfigureAwait(false);
        warnings.AddRange(fullWarnings);

        List<DuplicateGroup> groups = byFullHash
            .Where(pair => pair.Value.Count > 1)
            .Select(pair => new DuplicateGroup(pair.Key, pair.Value[0].Length, pair.Value))
            .OrderByDescending(g => g.ReclaimableBytes)
            .ThenBy(g => g.Hash, StringComparer.Ordinal)
            .ToList();

        return new DuplicateScanResult(groups, warnings);
    }

    private async Task<(Dictionary<string, List<FileEntry>> Groups, List<string> Warnings)> GroupByAsync(
        IReadOnlyList<FileEntry> entries, Func<FileEntry, Task<string>> keySelector, CancellationToken ct)
    {
        var keys = new string?[entries.Count];
        var warnings = new ConcurrentBag<string>();

        await Parallel.ForEachAsync(
            Enumerable.Range(0, entries.Count),
            new ParallelOptions { MaxDegreeOfParallelism = options.Parallelism, CancellationToken = ct },
            async (i, token) =>
            {
                try
                {
                    keys[i] = await keySelector(entries[i]).ConfigureAwait(false);
                }
                catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
                {
                    warnings.Add($"skipped unreadable file: {entries[i].FullPath} ({ex.Message})");
                }
            }).ConfigureAwait(false);

        var groups = new Dictionary<string, List<FileEntry>>();
        for (int i = 0; i < entries.Count; i++)
        {
            if (keys[i] is not { } key) continue;
            if (!groups.TryGetValue(key, out List<FileEntry>? bucket))
                groups[key] = bucket = [];
            bucket.Add(entries[i]);
        }
        return (groups, [.. warnings]);
    }
}

using System.IO.Enumeration;

namespace DupeSweep;

/// <summary>Walks the requested roots, applying size/extension/exclude/symlink filtering as it goes.</summary>
public static class FileScanner
{
    public static IEnumerable<FileEntry> Enumerate(
        IReadOnlyList<string> roots,
        ScanOptions options,
        Action<string>? onWarning = null,
        Func<string, bool, (List<string> Files, List<string> Directories)>? listEntries = null,
        Func<string, string>? directoryResolver = null)
    {
        var seenPaths = new HashSet<string>(PathComparer);
        var visitedDirectories = new HashSet<string>(PathComparer);
        var entryEnumerator = listEntries ?? DefaultListEntries;
        var resolveDirectory = directoryResolver ?? DefaultResolveDirectory;

        foreach (string root in roots)
        {
            string fullRoot = Path.GetFullPath(root);
            if (!Directory.Exists(fullRoot))
                throw new DirectoryNotFoundException($"directory not found: {root}");

            if (options.FollowSymlinks)
            {
                visitedDirectories.Add(resolveDirectory(fullRoot));
            }

            foreach (FileEntry entry in EnumerateDirectory(fullRoot, options, onWarning, entryEnumerator, resolveDirectory, visitedDirectories))
            {
                if (seenPaths.Add(entry.FullPath))
                    yield return entry;
            }
        }
    }

    private static IEnumerable<FileEntry> EnumerateDirectory(
        string directory,
        ScanOptions options,
        Action<string>? onWarning,
        Func<string, bool, (List<string> Files, List<string> Directories)> listEntries,
        Func<string, string> resolveDirectory,
        HashSet<string> visitedDirectories)
    {
        (List<string> files, List<string> subdirectories) = ListEntries(directory, options.Recursive, onWarning, listEntries);

        foreach (string file in files)
        {
            FileEntry? entry = TryCreateEntry(file, options);
            if (entry is not null)
                yield return entry;
        }

        foreach (string subdirectory in subdirectories)
        {
            if (!options.FollowSymlinks && IsReparsePoint(subdirectory))
                continue;
            if (IsExcluded(subdirectory, options.Excludes))
                continue;

            if (options.FollowSymlinks)
            {
                string canonicalSubdir = resolveDirectory(subdirectory);
                if (!visitedDirectories.Add(canonicalSubdir))
                    continue;
            }

            foreach (FileEntry entry in EnumerateDirectory(subdirectory, options, onWarning, listEntries, resolveDirectory, visitedDirectories))
                yield return entry;
        }
    }

    private static (List<string> Files, List<string> Directories) ListEntries(
        string directory,
        bool recursive,
        Action<string>? onWarning,
        Func<string, bool, (List<string> Files, List<string> Directories)> listEntries)
    {
        try
        {
            return listEntries(directory, recursive);
        }
        catch (Exception ex) when (ex is UnauthorizedAccessException or IOException)
        {
            onWarning?.Invoke($"skipped unreadable directory: {directory} ({ex.Message})");
            return ([], []);
        }
    }

    private static (List<string> Files, List<string> Directories) DefaultListEntries(string directory, bool recursive)
    {
        var files = Directory.EnumerateFiles(directory).ToList();
        var directories = recursive ? Directory.EnumerateDirectories(directory).ToList() : [];
        return (files, directories);
    }

    private static string DefaultResolveDirectory(string path)
    {
        try
        {
            var info = new DirectoryInfo(path);
            if (info.Attributes.HasFlag(FileAttributes.ReparsePoint))
            {
                FileSystemInfo? target = info.ResolveLinkTarget(returnFinalTarget: true);
                if (target is not null)
                    return Path.GetFullPath(target.FullName);
            }
            return Path.GetFullPath(info.FullName);
        }
        catch (Exception ex) when (ex is UnauthorizedAccessException or IOException)
        {
            return Path.GetFullPath(path);
        }
    }

    private static FileEntry? TryCreateEntry(string path, ScanOptions options)
    {
        FileInfo info;
        try
        {
            info = new FileInfo(path);
            if (!info.Exists) return null;
        }
        catch (Exception ex) when (ex is UnauthorizedAccessException or IOException)
        {
            return null;
        }

        if (!options.FollowSymlinks && info.Attributes.HasFlag(FileAttributes.ReparsePoint))
            return null;
        if (info.Length < options.MinSizeBytes)
            return null;
        if (options.Extensions is { Length: > 0 } extensions &&
            !extensions.Contains(info.Extension, StringComparer.OrdinalIgnoreCase))
            return null;
        if (IsExcluded(path, options.Excludes))
            return null;

        return new FileEntry(info.FullName, info.Length, info.LastWriteTimeUtc);
    }

    private static bool IsReparsePoint(string path)
    {
        try
        {
            return File.GetAttributes(path).HasFlag(FileAttributes.ReparsePoint);
        }
        catch (Exception ex) when (ex is UnauthorizedAccessException or IOException)
        {
            return false;
        }
    }

    private static bool IsExcluded(string path, IReadOnlyList<string> excludePatterns)
    {
        if (excludePatterns.Count == 0) return false;

        string name = Path.GetFileName(path);
        foreach (string pattern in excludePatterns)
        {
            if (FileSystemName.MatchesSimpleExpression(pattern, name))
                return true;
        }
        return false;
    }

    private static StringComparer PathComparer =>
        OperatingSystem.IsWindows() ? StringComparer.OrdinalIgnoreCase : StringComparer.Ordinal;
}

namespace DupeSweep;

public static class Format
{
    private static readonly string[] Units = ["B", "KB", "MB", "GB", "TB", "PB"];

    public static string Bytes(long bytes)
    {
        if (bytes < 0) throw new ArgumentOutOfRangeException(nameof(bytes));

        double value = bytes;
        int unit = 0;
        while (value >= 1024 && unit < Units.Length - 1)
        {
            value /= 1024;
            unit++;
        }
        return unit == 0 ? $"{bytes} {Units[unit]}" : $"{value:0.##} {Units[unit]}";
    }

    public static string Duration(TimeSpan elapsed) =>
        elapsed.TotalMinutes >= 1 ? $"{elapsed:mm\\:ss}" : $"{elapsed.TotalSeconds:0.0}s";
}

using System.Security.Cryptography;

namespace DupeSweep;

/// <summary>Two-tier hashing: a cheap sample hash to narrow candidates, then a full hash to confirm.</summary>
public static class Hashing
{
    private const int QuickHashSampleBytes = 64 * 1024;

    /// <summary>Hashes up to the first 64 KB of the file. Cheap enough to run on every same-size candidate.</summary>
    public static string ComputeQuickHash(string path, long fileLength, CancellationToken ct)
    {
        using SHA256 sha256 = SHA256.Create();
        using FileStream stream = File.OpenRead(path);

        int sampleSize = (int)Math.Min(fileLength, QuickHashSampleBytes);
        if (sampleSize == 0)
            return Convert.ToHexString(sha256.ComputeHash([]));

        byte[] buffer = new byte[sampleSize];
        int read = ReadFully(stream, buffer, ct);
        return Convert.ToHexString(sha256.ComputeHash(buffer, 0, read));
    }

    /// <summary>Hashes the entire file. Only run on files whose quick hash already collided.</summary>
    public static async Task<string> ComputeFullHashAsync(string path, CancellationToken ct)
    {
        await using FileStream stream = File.OpenRead(path);
        byte[] hash = await SHA256.HashDataAsync(stream, ct).ConfigureAwait(false);
        return Convert.ToHexString(hash);
    }

    private static int ReadFully(Stream stream, byte[] buffer, CancellationToken ct)
    {
        int total = 0;
        while (total < buffer.Length)
        {
            ct.ThrowIfCancellationRequested();
            int read = stream.Read(buffer, total, buffer.Length - total);
            if (read == 0) break;
            total += read;
        }
        return total;
    }
}

using System.Text.Json;

namespace DupeSweep;

internal static class DupeSweepJson
{
    public static readonly JsonSerializerOptions Options = new()
    {
        WriteIndented = true,
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
    };
