namespace DupeSweep;

/// <summary>Chooses which file in a duplicate group survives, per the requested strategy.</summary>
public static class KeepSelector
{
    public static FileEntry SelectKeeper(IReadOnlyList<FileEntry> files, KeepStrategy strategy) => strategy switch
    {
        KeepStrategy.First => files[0],
        KeepStrategy.Oldest => files.OrderBy(f => f.LastWriteTimeUtc).ThenBy(f => f.FullPath, StringComparer.Ordinal).First(),
        KeepStrategy.Newest => files.OrderByDescending(f => f.LastWriteTimeUtc).ThenBy(f => f.FullPath, StringComparer.Ordinal).First(),
        KeepStrategy.ShortestPath => files.OrderBy(f => f.FullPath.Length).ThenBy(f => f.FullPath, StringComparer.Ordinal).First(),
        _ => throw new ArgumentOutOfRangeException(nameof(strategy), strategy, "unknown keep strategy"),
    };

    public static DuplicateResolution Resolve(DuplicateGroup group, KeepStrategy strategy)
    {
        FileEntry keeper = SelectKeeper(group.Files, strategy);
        List<FileEntry> duplicates = group.Files.Where(f => f.FullPath != keeper.FullPath).ToList();
        return new DuplicateResolution(group, keeper, duplicates);
    }
}

namespace DupeSweep;

/// <summary>A scanned file and the metadata needed to group and select among duplicates.</summary>
public sealed record FileEntry(string FullPath, long Length, DateTime LastWriteTimeUtc);

/// <summary>A set of files confirmed byte-identical by a full SHA-256 hash match.</summary>
public sealed record DuplicateGroup(string Hash, long FileSize, IReadOnlyList<FileEntry> Files)
{
    public long ReclaimableBytes => FileSize * (Files.Count - 1);
}

/// <summary>A duplicate group with one file chosen to keep and the rest marked for action.</summary>
public sealed record DuplicateResolution(DuplicateGroup Group, FileEntry Keep, IReadOnlyList<FileEntry> Duplicates);

/// <summary>The groups found by a scan, plus any files that could not be read.</summary>
public sealed record DuplicateScanResult(IReadOnlyList<DuplicateGroup> Groups, IReadOnlyList<string> Warnings);

/// <summary>One quarantined file's original and quarantine location, enabling <c>dsweep restore</c>.</summary>
public sealed record ManifestEntry(string OriginalPath, string QuarantinePath, long Length, string Hash);

/// <summary>Outcome of a restore run.</summary>
public sealed record RestoreSummary(int Restored, int Skipped, IReadOnlyList<string> Messages);

using System.Diagnostics;
using System.Text;

namespace DupeSweep;

/// <summary>CLI entrypoint: parses options, scans, groups duplicates, reports, then optionally acts.</summary>
public static class Program
{
    public static async Task<int> Main(string[] args)
    {
        Console.OutputEncoding = Encoding.UTF8;

        ScanOptions options;
        try
        {
            options = CommandLine.Parse(args);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"dsweep: {ex.Message}");
            return 2;
        }

        if (options.ShowVersion)
        {
            Console.WriteLine(BuildInfo.Describe());
            return 0;
        }

        if (options.Help)
        {
            Console.WriteLine(CommandLine.Usage);
            return 0;
        }

        using var cancellation = new CancellationTokenSource();
        Console.CancelKeyPress += (_, e) =>
        {
            e.Cancel = true;
            Console.Error.WriteLine("\ndsweep: cancelling…");
            cancellation.Cancel();
        };

        try
        {
            return options.RestoreMode
                ? RunRestore(options)
                : await RunScanAsync(options, cancellation.Token).ConfigureAwait(false);
        }
        catch (OperationCanceledException)
        {
            Console.Error.WriteLine("dsweep: cancelled.");
            return 130;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"dsweep: fatal: {ex.Message}");
            return 1;
        }
    }

    private static async Task<int> RunScanAsync(ScanOptions options, CancellationToken ct)
    {
        if (options.Roots.Count == 0)
        {
            Console.WriteLine(CommandLine.Usage);
            return 1;
        }

        var stopwatch = Stopwatch.StartNew();

        List<FileEntry> entries;
        try
        {
            Action<string>? onWarning = options.Verbose
                ? warning => Console.Error.WriteLine($"dsweep: {warning}")
                : null;
            entries = FileScanner.Enumerate(options.Roots, options, onWarning).ToList();
        }
        catch (DirectoryNotFoundException ex)
        {
            Console.Error.WriteLine($"dsweep: {ex.Message}");
            return 1;
        }

        if (!options.Quiet)
            Console.Error.WriteLine($"dsweep: scanned {entries.Count} file(s), hashing candidates…");

        var finder = new DuplicateFinder(options);
        DuplicateScanResult scanResult = await finder.FindGroupsAsync(entries, ct).ConfigureAwait(false);

        if (options.Verbose)
            foreach (string warning in scanResult.Warnings)
                Console.Error.WriteLine($"dsweep: {warning}");

        List<DuplicateResolution> resolutions = scanResult.Groups
            .Select(g => KeepSelector.Resolve(g, options.Keep))
            .ToList();

        if (options.Json)
            Console.WriteLine(ReportWriter.WriteJson(resolutions));
        else
            ReportWriter.WriteText(Console.Out, resolutions);

        if (options.Apply != ApplyMode.None && resolutions.Count > 0)
            ApplyResolutions(options, resolutions);

        if (!options.Quiet)
            Console.Error.WriteLine($"dsweep: done in {Format.Duration(stopwatch.Elapsed)}.");

        return 0;
    }

    private static void ApplyResolutions(ScanOptions options, List<DuplicateResolution> resolutions)
    {
        if (options.Apply == ApplyMode.Quarantine)
        {
            string quarantineDir = options.QuarantineDir
                ?? Path.Combine(Path.GetFullPath(options.Roots[0]), ".dupesweep-quarantine");

            IReadOnlyList<ManifestEntry> manifest = QuarantineService.Quarantine(resolutions, quarantineDir);
            string manifestPath = Path.Combine(Path.GetFullPath(quarantineDir), "manifest.json");

            if (!options.Quiet)
                Console.Error.WriteLine(
                    $"dsweep: quarantined {manifest.Count} file(s) to {quarantineDir} (manifest: {manifestPath}).");
        }
        else if (options.Apply == ApplyMode.Delete)
        {
            int deleted = 0;
            foreach (DuplicateResolution resolution in resolutions)
            {
                foreach (FileEntry duplicate in resolution.Duplicates)
                {
                    File.Delete(duplicate.FullPath);
                    deleted++;
                }
            }

            if (!options.Quiet)
                Console.Error.WriteLine($"dsweep: permanently deleted {deleted} file(s).");
        }
    }

    private static int RunRestore(ScanOptions options)
    {
        if (string.IsNullOrEmpty(options.ManifestPath))
        {
            Console.WriteLine(CommandLine.Usage);
            return 1;
        }

        IReadOnlyList<ManifestEntry> manifest = RestoreService.ReadManifest(options.ManifestPath);
        RestoreSummary summary = RestoreService.Restore(manifest, options.DryRun);

        if (!options.Quiet)
            foreach (string message in summary.Messages)
                Console.WriteLine(message);

        Console.WriteLine(
            $"dsweep: restore {(options.DryRun ? "preview" : "complete")} — {summary.Restored} restored, {summary.Skipped} skipped.");

        return summary.Restored == 0 && summary.Skipped > 0 ? 1 : 0;
    }
}

using System.Globalization;
using System.Text.Json;

namespace DupeSweep;

/// <summary>
/// Plans and moves duplicates into a quarantine folder, writing a durable manifest
/// before the first move so a partial operation remains recoverable.
/// </summary>
public static class QuarantineService
{
    public static IReadOnlyList<ManifestEntry> Quarantine(IReadOnlyList<DuplicateResolution> resolutions, string quarantineDir)
    {
        string fullQuarantineDir = Path.GetFullPath(quarantineDir);
        string manifestPath = Path.Combine(fullQuarantineDir, "manifest.json");
        if (PathExists(manifestPath))
            throw new InvalidOperationException($"refusing to reuse existing quarantine manifest: {manifestPath}");

        Directory.CreateDirectory(fullQuarantineDir);
        var manifest = Plan(resolutions, fullQuarantineDir);

        // CreateNew closes the check/create race and ensures an existing manifest is
        // never replaced. Flush the complete journal before moving any source file.
        WriteManifest(manifest, manifestPath);

        foreach (ManifestEntry entry in manifest)
            File.Move(entry.OriginalPath, entry.QuarantinePath);

        return manifest;
    }

    public static void WriteManifest(IReadOnlyList<ManifestEntry> manifest, string manifestPath)
    {
        string? directory = Path.GetDirectoryName(manifestPath);
        if (!string.IsNullOrEmpty(directory))
            Directory.CreateDirectory(directory);

        string json = JsonSerializer.Serialize(manifest, DupeSweepJson.Options);
        using var stream = new FileStream(manifestPath, FileMode.CreateNew, FileAccess.Write, FileShare.None);
        using var writer = new StreamWriter(stream);
        writer.Write(json);
        writer.Flush();
        stream.Flush(flushToDisk: true);
    }

    private static List<ManifestEntry> Plan(IReadOnlyList<DuplicateResolution> resolutions, string quarantineDir)
    {
        var manifest = new List<ManifestEntry>();
        var reservedDestinations = new HashSet<string>(PathComparer);

        for (int groupIndex = 0; groupIndex < resolutions.Count; groupIndex++)
        {
            DuplicateResolution resolution = resolutions[groupIndex];
            if (resolution.Duplicates.Count == 0) continue;

            string groupDir = Path.Combine(quarantineDir, groupIndex.ToString(CultureInfo.InvariantCulture));
            Directory.CreateDirectory(groupDir);

            foreach (FileEntry duplicate in resolution.Duplicates)
            {
                string originalPath = Path.GetFullPath(duplicate.FullPath);
                string destination = UniqueDestination(groupDir, Path.GetFileName(originalPath), reservedDestinations);
                reservedDestinations.Add(destination);
                manifest.Add(new ManifestEntry(originalPath, destination, duplicate.Length, resolution.Group.Hash));
            }
        }

        return manifest;
    }

    private static string UniqueDestination(string directory, string fileName, ISet<string> reservedDestinations)
    {
        if (string.IsNullOrEmpty(fileName))
            throw new ArgumentException("duplicate path must have a file name", nameof(fileName));

        string destination = Path.Combine(directory, fileName);
        if (!PathExists(destination) && !reservedDestinations.Contains(destination)) return destination;

        string extension = Path.GetExtension(fileName);
        string baseName = Path.GetFileNameWithoutExtension(fileName);
        for (int suffix = 2; ; suffix++)
        {
            string candidate = Path.Combine(directory, $"{baseName}_{suffix}{extension}");
            if (!PathExists(candidate) && !reservedDestinations.Contains(candidate)) return candidate;
        }
    }

    private static bool PathExists(string path) => File.Exists(path) || Directory.Exists(path);

    private static StringComparer PathComparer =>
        OperatingSystem.IsWindows() ? StringComparer.OrdinalIgnoreCase : StringComparer.Ordinal;
}

using System.Text.Json;

namespace DupeSweep;

/// <summary>Renders duplicate-group resolutions as either human-readable text or JSON.</summary>
public static class ReportWriter
{
    public static void WriteText(TextWriter writer, IReadOnlyList<DuplicateResolution> resolutions)
    {
        if (resolutions.Count == 0)
        {
            writer.WriteLine("dsweep: no duplicates found.");
            return;
        }

        long totalReclaimable = 0;
        int totalDuplicateFiles = 0;

        for (int i = 0; i < resolutions.Count; i++)
        {
            DuplicateResolution resolution = resolutions[i];
            totalReclaimable += resolution.Group.ReclaimableBytes;
            totalDuplicateFiles += resolution.Duplicates.Count;

            writer.WriteLine(
                $"[{i + 1}] {Format.Bytes(resolution.Group.FileSize)} x {resolution.Group.Files.Count} copies  (sha256 {resolution.Group.Hash[..12]}…)");
            writer.WriteLine($"    KEEP      {resolution.Keep.FullPath}");
            foreach (FileEntry duplicate in resolution.Duplicates)
                writer.WriteLine($"    DUPLICATE {duplicate.FullPath}");
        }

        writer.WriteLine();
        writer.WriteLine(
            $"dsweep: {resolutions.Count} duplicate group(s), {totalDuplicateFiles} reclaimable file(s), {Format.Bytes(totalReclaimable)} reclaimable.");
    }

    public static string WriteJson(IReadOnlyList<DuplicateResolution> resolutions)
    {
        var payload = new
        {
            groups = resolutions.Select(r => new
            {
                hash = r.Group.Hash,
                fileSize = r.Group.FileSize,
                reclaimableBytes = r.Group.ReclaimableBytes,
                keep = r.Keep.FullPath,
                duplicates = r.Duplicates.Select(d => d.FullPath).ToArray(),
            }),
            summary = new
            {
                groupCount = resolutions.Count,
                duplicateFileCount = resolutions.Sum(r => r.Duplicates.Count),
                reclaimableBytes = resolutions.Sum(r => r.Group.ReclaimableBytes),
            },
        };
        return JsonSerializer.Serialize(payload, DupeSweepJson.Options);
    }
}

using System.Text.Json;

namespace DupeSweep;

/// <summary>Reads a quarantine manifest and moves files back to their original locations.</summary>
public static class RestoreService
{
    public static IReadOnlyList<ManifestEntry> ReadManifest(string manifestPath)
    {
        if (!File.Exists(manifestPath))
            throw new FileNotFoundException($"manifest not found: {manifestPath}");

        string json = File.ReadAllText(manifestPath);
        return JsonSerializer.Deserialize<List<ManifestEntry>>(json, DupeSweepJson.Options)
               ?? throw new InvalidDataException($"manifest is empty or invalid: {manifestPath}");
    }

    public static RestoreSummary Restore(IReadOnlyList<ManifestEntry> manifest, bool dryRun)
    {
        int restored = 0;
        int skipped = 0;
        var messages = new List<string>();

        foreach (ManifestEntry entry in manifest)
        {
            if (!File.Exists(entry.QuarantinePath))
            {
                messages.Add($"skip: quarantined file missing: {entry.QuarantinePath}");
                skipped++;
                continue;
            }
            if (File.Exists(entry.OriginalPath))
            {
                messages.Add($"skip: destination already exists: {entry.OriginalPath}");
                skipped++;
                continue;
            }

            if (dryRun)
            {
                messages.Add($"would restore: {entry.QuarantinePath} -> {entry.OriginalPath}");
                restored++;
                continue;
            }

            string? directory = Path.GetDirectoryName(entry.OriginalPath);
            if (!string.IsNullOrEmpty(directory))
                Directory.CreateDirectory(directory);

            File.Move(entry.QuarantinePath, entry.OriginalPath);
            messages.Add($"restored: {entry.OriginalPath}");
            restored++;
        }

        return new RestoreSummary(restored, skipped, messages);
    }
}

namespace DupeSweep;

public enum ApplyMode { None, Quarantine, Delete }

public enum KeepStrategy { First, Oldest, Newest, ShortestPath }

/// <summary>Parsed CLI configuration for both scan mode and restore mode.</summary>
public sealed class ScanOptions
{
    public bool Help { get; set; }
    public bool ShowVersion { get; set; }
    public List<string> Roots { get; } = [];
    public bool Recursive { get; set; } = true;
    public long MinSizeBytes { get; set; } = 1;
    public string[]? Extensions { get; set; }
    public List<string> Excludes { get; } = [];
    public bool FollowSymlinks { get; set; }
    public bool Json { get; set; }
    public ApplyMode Apply { get; set; } = ApplyMode.None;
    public string? QuarantineDir { get; set; }
    public KeepStrategy Keep { get; set; } = KeepStrategy.First;
    public int Parallelism { get; set; } = Math.Clamp(Environment.ProcessorCount, 1, 64);
    public bool Quiet { get; set; }
    public bool Verbose { get; set; }

    public bool RestoreMode { get; set; }
    public string? ManifestPath { get; set; }
    public bool DryRun { get; set; }
}

