                    throw new UnauthorizedAccessException("Access is denied.");

                return (
                    [accessibleFile],
                    [forbiddenSubdir]
                );
            }).ToList();

        Assert.Single(entries);
        Assert.Equal(Path.GetFullPath(accessibleFile), entries[0].FullPath);
